@startuml

class Well {
  + code : string
  + pollutionRate() : double
}

abstract class Company {
  + taxCode : string
  + numberOfEmployees : int
}

class OnshoreWell {
  + surfaceExtension : double
}

class OffshoreWell {
  + yearOfInstallation : int
  + geographicalAreaCode : string
  + environmentalImportance : int
}

class OilCompany {}

class ExtractsFrom {
  + quantity : double
}

OilCompany --|> Company
OnshoreWell --|> Well
OffshoreWell --|> Well
Well "1" -- "*" Company : extractedBy
Well "1" -- "*" ExtractsFrom

@enduml

